/**
 * Splits an encoded query string into its decoded [name, value] pairs.
 * The splitting is done on the still-encoded string so that escaped separators
 * (like %26 for '&' or %3D for '=') are kept as part of the name/value instead of
 * being interpreted as separators.
 */
private static List<String[]> parseQuery(String encodedQuery) {
    var parameters = new ArrayList<String[]>();
    if (encodedQuery == null) return parameters;

    for (var pair : encodedQuery.split("&")) {
        if (pair.isEmpty()) continue;
        // only the first '=' separates the name from the value
        var separator = pair.indexOf('=');
        var name = separator < 0 ? pair : pair.substring(0, separator);
        var value = separator < 0 ? "" : pair.substring(separator + 1);
        // decode only now, once each part is already isolated
        parameters.add(new String[]{UrlUtils.decode(name), UrlUtils.decode(value)});
    }

    return parameters;
}

